void format_log_entry(char *out, size_t out_len, const char *level, const char *message) {
    // Calculate the maximum length for the log level and message
    size_t max_len = out_len - 1; // Leave space for the null terminator
    size_t level_len = strlen(level);
    size_t message_len = strlen(message);

    // Calculate the remaining space for the log level and message
    size_t remaining_space = max_len - level_len - message_len;

    // If there's not enough space, truncate the log level and message
    if (remaining_space < 0) {
        level_len = max_len;
        message_len = max_len;
    }

    // Write the log level
    strncpy(out, level, level_len);
    out[level_len] = '\0'; // Null terminate the log level

    // Write the space between the log level and message
    out[level_len + 1] = ' ';

    // Write the message
    strncpy(out + level_len + 2, message, message_len);
    out[level_len + 2 + message_len] = '\0'; // Null terminate the message
}
