/**
 * Reads one line from standard input into the buffer `out`, 
 * whose size in bytes is `out_len`, and removes the trailing newline.
 * 
 * @param out The buffer to store the read line.
 * @param out_len The size of the buffer in bytes.
 */
void read_username(char *out, size_t out_len) {
    // Read a line from standard input
    size_t len = read(STDIN_FILENO, out, out_len);

    // If the read was successful, remove the trailing newline
    if (len > 0 && out[len - 1] == '\n') {
        out[len - 1] = '\0';
        len--;
    }

    // If the read was not successful, leave the buffer empty
    if (len == 0) {
        out[0] = '\0';
    }
}
