def save_params(params, path):
    """
    Saves a dictionary of layer names to float values into a file.

    Args:
    params (dict): A dictionary where keys are layer names and values are lists of floats.
    path (str): The path to the file where the dictionary will be saved.

    Returns:
    None
    """
    try:
        with open(path, 'w') as file:
            for layer, values in params.items():
                file.write(f"{layer}: {', '.join(map(str, values))}\n")
    except Exception as e:
        print(f"Error saving parameters: {e}")


def load_params(path):
    """
    Loads a dictionary of layer names to float values from a file.

    Args:
    path (str): The path to the file where the dictionary will be loaded.

    Returns:
    dict: A dictionary where keys are layer names and values are lists of floats.
    """
    try:
        with open(path, 'r') as file:
            params = {}
            for line in file:
                layer, values = line.strip().split(': ')
                values = list(map(float, values.split(', ')))
                params[layer] = values
        return params
    except FileNotFoundError:
        print("File not found.")
        return {}
    except Exception as e:
