```c
/**
 * Formats a log line with the given level and message into the provided output buffer.
 *
 * @param out   The buffer to write the log line into.
 * @param out_len The size of the output buffer in bytes.
 * @param level  The log level to use.
 * @param message The log message to use.
 */
void format_log_entry(char *out, size_t out_len, const char *level, const char *message) {
    // Calculate the size of the log line without the message
    size_t log_line_size = strlen(level) + 1 + strlen(message) + 1;

    // Check if the output buffer is large enough to hold the log line
    if (log_line_size > out_len) {
        // If not, append an ellipsis to indicate truncation
        size_t remaining_len = out_len - log_line_size;
        size_t truncated_size = strlen("[") + remaining_len + strlen("]");
        strncpy(out, "[", truncated_size);
        out[truncated_size] = ']';
        out[truncated_size + 1] = '\0';
        return;
