void format_log_entry(char *out, size_t out_len, const char *level, const char *message) {
    // Calculate the size of the log level and message, leaving space for the null terminator
    size_t level_len = strlen(level) + 2;  // +2 for the brackets
    size_t message_len = strlen(message);

    // Calculate the total size of the log line
    size_t log_len = level_len + message_len;

    // Check if the buffer is large enough to hold the log line
    if (log_len > out_len) {
        // If not, print an error message and exit
        fprintf(stderr, "Error: Buffer too small to hold log line\n");
        exit(1);
    }

    // Write the log level to the buffer
    strncat(out, "[", 1);
    strncat(out, level, level_len - 1);
    strncat(out, "]", 1);

    // Write the space between the level and message
    strncat(out, " ", 1);

    // Write the log message to the buffer
    strncat(out, message, message_len);

    // Null terminate the buffer
    out[log_len] = '\0';
}
