import subprocess

def disk_usage(directory):
    """
    Returns the human-readable total size of the given directory as reported by the system command 'du -sh'.

    Parameters:
    directory (str): The path to the directory for which to retrieve the disk usage.

    Returns:
    str: The total size of the given directory in a human-readable format, such as "12K".
    """
    try:
        # Run the du command to get the total size of the given directory
        output = subprocess.check_output(['du', '-sh', directory]).decode('utf-8')
    except FileNotFoundError:
        # If the 'du' command is not found, return an error message
        return "Error: 'du' command not found. Please install the 'coreutils' package to continue."
    except subprocess.CalledProcessError as e:
        # If the 'du' command fails, return an error message
        return f"Error: {e}"
    else:
        # Split the output into lines and extract the size
        for line in output.split('\n'):
            parts = line.split()
            if len(parts) > 1:
                size, unit = parts[1], parts[2]
                # Convert the size to bytes and return it as a human-readable string
                if unit == 'B':
                    return f"{int(size)}B"
                elif unit == 'K':
                    return f"{int(size)}K"
                elif unit == 'M':
                    return f"{int(size)}M"
                elif unit == 'G':
                    return f"{int(size)}G"
                elif unit == 'T':
                    return f"{int(size)}T"
                elif unit == 'P':
                    return f"{int(size)}P"
                else:
                    # If the unit is not recognized, return an error message
                    return f"Error: Unknown unit '{unit}' for size '{size}'"
        # If no size is found, return an error message
        return "Error: No size found for the given directory"
