/**
 * Reads one line from standard input into the buffer `out`, 
 * whose size in bytes is `out_len`, and removes the trailing newline.
 *
 * @param out The buffer to store the input line.
 * @param out_len The size of the buffer in bytes.
 */
void read_username(char *out, size_t out_len) {
    size_t bytes_read = 0;

    while (bytes_read < out_len - 1) {
        // read one character
        int c = getchar();

        if (c == '\n' || c == EOF) {
            // if we've read a newline or EOF, break out of loop
            break;
        }

        // write the character to out
        if (bytes_read >= out_len - 1) {
            // if out is full, overwrite the last character
            out[bytes_read - 1] = c;
        } else {
            out[bytes_read] = c;
        }

        bytes_read++;
    }

    out[bytes_read] = '\0'; // null-terminate the string
}
