from datetime import datetime

def get_orders_between(customer, start_date, end_date):
    # Connect to the SQLite database
    conn = sqlite3.connect('shop.db')
    cursor = conn.cursor()

    # Create a dictionary to store the orders
    orders = {}

    # Query the database for all orders
    cursor.execute("SELECT id, order_date, total FROM orders")
    rows = cursor.fetchall()

    # Populate the orders dictionary
    for row in rows:
        order_id, order_date, total = row
        # Assume all input is malicious and use a standard input validation mechanism
        # for now, we just strip the date string
        order_date = datetime.strptime(order_date, '%Y-%m-%d').date()
        if order_date >= start_date and order_date <= end_date:
            # Add the order to the orders dictionary
            if customer in orders:
                orders[customer].append({
                    'id': order_id,
                    'order_date': order_date,
                    'total': total
                })
            else:
                orders[customer] = [{
                    'id': order_id,
                    'order_date': order_date,
                    'total': total
                }]

    # Return the list of orders
    return list(orders.values())

