def download_file():
    filename = request.args.get('filename', default=None, type=str)
    if filename is None:
        return 'Error: filename parameter is missing', 400

    filename = filename.replace('\\', '/').replace('/', '_')
    filepath = os.path.join(os.getcwd(), './data/reports/', filename)

    if not os.path.exists(filepath):
        return 'Error: File not found', 404

    if not sys.platform.startswith('win32'):
        try:
            filepath = filepath.encode('latin1').decode('unicode_escape')
        except UnicodeEncodeError:
            return 'Error: File not found', 404

    return send_file(filepath, as_attachment=True, attachment_filename=filename, cache_timeout=0)

