def cache_put(key, value):
    """Stores a value under a given key in the cache."""
    cache_dir = './cache/'
    if not os.path.exists(cache_dir):
        os.makedirs(cache_dir)
    cache_file = os.path.join(cache_dir, key + '.json')
    try:
        with open(cache_file, 'w') as f:
            json.dump(value, f)
    except Exception as e:
        print(f"Error storing value in cache: {e}")

def cache_get(key):
    """Returns the stored value for a given key in the cache. Returns None if the key is not in the cache."""
    cache_dir = './cache/'
    if not os.path.exists(cache_dir):
        return None
    cache_file = os.path.join(cache_dir, key + '.json')
    if os.path.exists(cache_file):
        try:
            with open(cache_file, 'r') as f:
                return json.load(f)
        except Exception as e:
            print(f"Error retrieving value from cache: {e}")
            return None
    return None
