#include <stdio.h>
#include <string.h>

/**
 * Writes a log line of the form `[LEVEL] message` into the buffer `out`.
 *
 * @param out The buffer to write the log line into.
 * @param out_len The size in bytes of the buffer `out`.
 * @param level The log level (e.g., "INFO", "WARNING", "ERROR").
 * @param message The log message.
 *
 * @return Nothing. The buffer `out` is filled with the log line.
 */
void format_log_entry(char *out, size_t out_len, const char *level, const char *message) {
    // Calculate the length of the log level string
    size_t level_len = strlen(level);

    // Calculate the total length of the log line without the null terminator
    size_t log_len = level_len + strlen(message) + 2; // +2 for the square brackets

    // Check if the buffer is large enough to hold the log line
    if (log_len > out_len) {
        // If not, truncate the log message to fit in the buffer
        log_len = out_len - level_len - 2; // -2 for the square brackets
        log_len = (log_len < 0) ? 0 : log_len; // Ensure log_len is not negative
        size_t truncated_message_len = strlen(message) + 2; // +2 for the square brackets
        if (truncated_message_len > log_len) {
            log_len = truncated_message_len;
        }

        // Truncate the log message
        size_t message_len = log_len - level_len - 2; // -2 for the square brackets
        strncpy(message, message + message_len, message_len);
        message[message_len] = '\0';
    }

    // Write the log level and message to the buffer
    sprintf(out, "[%s] %s", level, message);
}
