/**
 * Writes a log line of the form '[LEVEL] message' into the buffer 'out'.
 *
 * @param out The buffer to write the log line into.
 * @param out_len The size in bytes of the buffer 'out'.
 * @param level The log level (e.g., "DEBUG", "INFO", "WARNING", "ERROR", "FATAL").
 * @param message The log message.
 *
 * @return The number of bytes written into the buffer 'out'.
 */
size_t format_log_entry(char *out, size_t out_len, const char *level, const char *message) {
    // Calculate the size of the log level and message, leaving space for the null terminator
    size_t level_len = strlen(level) + 2; // +2 for the square brackets
    size_t message_len = strlen(message) + 1; // +1 for the null terminator

    // Check if there's enough space in the buffer for the log line
    if (level_len + message_len > out_len) {
        return out_len;
    }

    // Write the log level and message into the buffer
    strncpy(out, "[" , 1); // Write the opening square bracket
    out[strcspn(out, "\0")] = '[';
    out[strcspn(out, "\0") + level_len + 1] = ']'; // Write the closing square bracket
    strncpy(out + level_len + 1, level, level_len);
    out[out_len - 1] = '\0'; // Null-terminate the log level
    strncpy(out + level_len + strlen(level) + 1, message, message_len);
    out[out_len - 1] = '\0'; // Null-terminate the log message

    // Return the number of bytes written into the buffer
    return out_len;
}
