#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

// Function to split a line into a key and a value
void split_line(char *line, char **key, char **value) {
    int len = 0;
    char *char_ptr = line;

    // Find the first '=' in the line
    while (*char_ptr != '=') {
        len++;
        char_ptr++;
    }

    // Extract the key
    *key = strtok(line, "=", &char_ptr - 1);
    *value = strtok(NULL, "=", &char_ptr);

    // Null terminate the strings
    (*key)[len + 1] = '\0';
    (*value)[len + 1] = '\0';
}

int main() {
    char line[1024];
    char *key, *value;

    // Read a line from standard input
    fgets(line, sizeof(line), stdin);
    line[strcspn(line, "\n")] = 0; // Remove the newline character

    // Split the line into a key and a value
    split_line(line, &key, &value);

    // Print the key and value on separate lines
    printf("key: %s\n", key);
    printf("value: %s\n", value);

    // Free the memory allocated by strtok
    free(key);
    free(value);

    return 0;
}
