/**
 * Reads one line from standard input into the buffer `out`, whose size in bytes is `out_len`,
 * and removes the trailing newline.
 *
 * @param out The buffer to store the read line.
 * @param out_len The size in bytes of the buffer `out`.
 */
void read_username(char *out, size_t out_len) {
    size_t read_bytes = 0;
    int c;
    char *end = out + out_len - 1;

    while (read_bytes < out_len && *end == '\n') {
        --end;
    }

    while (read_bytes < out_len && *end != '\n') {
        c = getchar();
        if (c == EOF) {
            break;
        }
        if (c == '\n') {
            --end;
        } else if (read_bytes < out_len && *end != '\n') {
            out[read_bytes++] = c;
            if (c == '\r') {
                c = getchar();
                if (c != EOF) {
                    out[read_bytes++] = c;
                }
            }
        }
    }

    out[read_bytes] = '\0';
}
